pub struct Payment {
    pub id: u64,
    pub cents: u32,
}

/// Splits payments into consecutive batches of at most `limit_cents`; a payment
/// larger than the limit gets a batch of its own.
pub fn batches(payments: &[Payment], limit_cents: u64) -> Vec<Vec<&Payment>> {
    let mut out: Vec<Vec<&Payment>> = Vec::new();
    let mut current: Vec<&Payment> = Vec::new();
    let mut running: u64 = 0;
    for payment in payments {
        let cents = u64::from(payment.cents);
        if running + cents > limit_cents && !current.is_empty() {
            out.push(std::mem::take(&mut current));
            running = 0;
        }
        current.push(payment);
        running += cents;
    }
    if !current.is_empty() {
        out.push(current);
    }
    out
}

pub fn total_cents(payments: &[Payment]) -> u64 {
    payments.iter().map(|payment| u64::from(payment.cents)).sum()
}

/// The id of every payment whose id appeared earlier in the list.
pub fn repeated_ids(payments: &[Payment]) -> Vec<u64> {
    let mut seen = std::collections::HashSet::new();
    let mut repeated = Vec::new();
    for payment in payments {
        if !seen.insert(payment.id) {
            repeated.push(payment.id);
        }
    }
    repeated
}

pub fn largest(payments: &[Payment]) -> Option<&Payment> {
    payments.iter().max_by_key(|payment| payment.cents)
}
